export const envelope = [27, 26, 27];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 13;
  const cz = 13;
  const sy = 5; // Seat plane at y = 5 allows 5 blocks of terrain conformity below seat

  // 3D voxel buffer for deterministic composition
  const grid = new Array(W * H * D).fill(null);

  function setV(x, y, z, b) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x + y * W + z * W * H] = b;
    }
  }

  function getV(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x + y * W + z * W * H];
    }
    return null;
  }

  // Deterministic coordinate-based hash for material variation
  function coordHash(x, y, z) {
    let h = (x * 374761393 + y * 668265263 + z * 127412617) ^ 0x5bf03635;
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
  }

  // Theme helper utilities
  const stonePrimary = api.theme.stone.primary;
  const stoneAccent = api.theme.stone.accent || stonePrimary;
  const pavement = api.theme.ground.pavement || stonePrimary;
  const plinth = api.theme.ground.plinth || stonePrimary;
  const kerb = api.theme.ground.kerb || pavement;
  const stoneWall = api.theme.stone.wall ? api.theme.stone.wall.split("[")[0] : "minecraft:stone_brick_wall";

  function makeStairs(stairBase, facing, half = "bottom", shape = "straight") {
    const base = stairBase.split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function makeSlab(slabBase, type = "bottom") {
    const base = slabBase.split("[")[0];
    return `${base}[type=${type}]`;
  }

  const themeStair = api.theme.stone.stairs || "minecraft:stone_brick_stairs";
  const themeSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";

  // -------------------------------------------------------------
  // 1. IMPACT CRATER BASIN & CONFORMING FOUNDATION
  // -------------------------------------------------------------
  const floorHeights = new Map();

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dist = Math.hypot(x - cx, z - cz);
      if (dist <= 13.0) {
        const rawH = api.heightAt(x, z);
        const terrainY = Math.max(0, Math.min(H - 2, Math.round(sy + rawH)));

        // Crater rim profile: sunken center, raised rim ring, outer apron
        let craterOffset = 0;
        if (dist < 3.8) {
          craterOffset = -1; // Central impact depression
        } else if (dist < 7.5) {
          craterOffset = 0; // Inner floor
        } else if (dist < 9.5) {
          craterOffset = 1; // Inner rim step
        } else if (dist < 11.8) {
          // Raised ejecta rim with undulating crest
          const angle = Math.atan2(z - cz, x - cx);
          const rimNoise = 0.5 * Math.sin(4 * angle) + 0.3 * Math.cos(7 * angle);
          craterOffset = 2 + Math.round(rimNoise);
        } else {
          craterOffset = 1; // Outer drop to street
        }

        const surfaceY = Math.max(terrainY, Math.min(H - 4, sy + craterOffset));
        const startY = Math.max(0, Math.min(terrainY, sy - 2));

        floorHeights.set(`${x},${z}`, surfaceY);

        // Fill column from ground up to crater surface
        for (let y = startY; y <= surfaceY; y++) {
          const rnd = coordHash(x, y, z);
          if (y === surfaceY) {
            if (dist < 5.0) {
              // Impact center scorched crust
              if (rnd < 0.35) setV(x, y, z, "minecraft:crying_obsidian");
              else if (rnd < 0.6) setV(x, y, z, "minecraft:blackstone");
              else if (rnd < 0.8) setV(x, y, z, "minecraft:magma_block");
              else setV(x, y, z, "minecraft:smooth_basalt");
            } else if (dist < 9.5) {
              // Inner plaza pavement cracked by impact
              if (rnd < 0.45) setV(x, y, z, pavement);
              else if (rnd < 0.7) setV(x, y, z, "minecraft:cracked_deepslate_tiles");
              else if (rnd < 0.85) setV(x, y, z, "minecraft:blackstone");
              else setV(x, y, z, stonePrimary);
            } else if (dist <= 11.8) {
              // Rim retaining wall & forge apron
              if (rnd < 0.5) setV(x, y, z, stonePrimary);
              else if (rnd < 0.8) setV(x, y, z, stoneAccent);
              else setV(x, y, z, kerb);
            } else {
              setV(x, y, z, pavement);
            }
          } else {
            // Sub-crater masonry & scorched rock
            if (rnd < 0.5) setV(x, y, z, stonePrimary);
            else if (rnd < 0.8) setV(x, y, z, "minecraft:blackstone");
            else setV(x, y, z, "minecraft:smooth_basalt");
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. RADIANT FRACTURE CREVASSES (Impact fissures)
  // -------------------------------------------------------------
  const fissures = [
    { angle: -2.35, len: 10.5, mat: ["minecraft:crying_obsidian", "minecraft:amethyst_block"] },
    { angle: -0.75, len: 11.0, mat: ["minecraft:gilded_blackstone", "minecraft:sea_lantern"] },
    { angle: 0.85, len: 10.0, mat: ["minecraft:magma_block", "minecraft:crying_obsidian"] },
    { angle: 2.30, len: 10.8, mat: ["minecraft:amethyst_block", "minecraft:crying_obsidian"] },
  ];

  for (const f of fissures) {
    const cosA = Math.cos(f.angle);
    const sinA = Math.sin(f.angle);
    for (let d = 2.5; d <= f.len; d += 0.5) {
      const fx = Math.round(cx + d * cosA + 0.3 * Math.sin(d * 1.5));
      const fz = Math.round(cz + d * sinA + 0.3 * Math.cos(d * 1.5));
      const fy = floorHeights.get(`${fx},${fz}`);
      if (fy !== undefined) {
        const rnd = coordHash(fx, fy, fz);
        const block = rnd < 0.6 ? f.mat[0] : f.mat[1];
        setV(fx, fy, fz, block);
        setV(fx, fy - 1, fz, f.mat[0]);
      }
    }
  }

  // -------------------------------------------------------------
  // 3. MAIN STAR-METAL METEORITE MONOLITH (Tilted Celestial Core)
  // -------------------------------------------------------------
  // Leaning axis from nose buried deep (P0) to soaring jagged peak (P1)
  const P0 = { x: 11.2, y: sy - 1.0, z: 11.0 };
  const P1 = { x: 15.6, y: sy + 15.6, z: 14.8 };
  const Lx = P1.x - P0.x;
  const Ly = P1.y - P0.y;
  const Lz = P1.z - P0.z;
  const Lsq = Lx * Lx + Ly * Ly + Lz * Lz;

  for (let x = 6; x <= 21; x++) {
    for (let y = sy - 2; y <= sy + 17; y++) {
      for (let z = 6; z <= 21; z++) {
        const vx = x - P0.x;
        const vy = y - P0.y;
        const vz = z - P0.z;
        const dot = vx * Lx + vy * Ly + vz * Lz;
        const t = dot / Lsq;

        if (t >= -0.1 && t <= 1.06) {
          const qx = P0.x + t * Lx;
          const qy = P0.y + t * Ly;
          const qz = P0.z + t * Lz;
          const distAxis = Math.hypot(x - qx, y - qy, z - qz);

          // Meteorite radius profile: bulbous center, tapering at peak
          const tClamped = Math.max(0, Math.min(1, t));
          let baseR = 5.3 * Math.sin(Math.PI * Math.pow(tClamped, 0.65) * 0.86 + 0.18);
          if (t < 0) baseR += t * 2.5;
          if (t > 0.8) baseR *= 1.0 - ((t - 0.8) / 0.26) * 0.72;

          // Angular crystalline facet harmonics
          const theta = Math.atan2(z - qz, x - qx);
          const facet1 = 1.05 * Math.cos(3 * theta + t * 2.2);
          const facet2 = 0.75 * Math.sin(5 * theta - t * 1.6);
          const facet3 = 0.45 * Math.cos(2 * theta + (y - sy) * 0.45);
          const maxR = baseR + facet1 + facet2 + facet3;

          // Cleavage planes (celestial crystalline cut facets)
          const cut1 = (x - cx) * 0.58 - (y - (sy + 7.5)) * 0.42 - (z - cz) * 0.68;
          const cut2 = -(x - cx) * 0.68 + (y - (sy + 9.5)) * 0.48 + (z - cz) * 0.48;
          const cut3 = (y - (sy + 13.8)) * 0.88 + (x - 14) * 0.32 + (z - 14) * 0.32;

          if (distAxis <= maxR && cut1 < 4.7 && cut2 < 4.8 && cut3 < 4.3) {
            // Star-metal internal rifts / radiant veins
            // Vein 1: Purple Star-Metal (Amethyst & Crying Obsidian)
            const v1 = Math.abs((x - cx) * 0.55 + (y - (sy + 7)) * -0.45 + (z - cz) * 0.7 - 0.4);
            // Vein 2: Cyan Radiant Heat (Sea Lantern & Gilded Blackstone)
            const v2 = Math.abs((x - 12.5) * -0.68 + (y - (sy + 9)) * -0.35 + (z - 13.5) * 0.64 + 0.8);
            // Vein 3: Meteoric Iron Seam (Raw Iron & Ancient Ore)
            const v3 = Math.abs((x - 13.5) * 0.35 + (y - (sy + 5)) * 0.8 + (z - 12.5) * 0.48 - 1.2);

            const rnd = coordHash(x, y, z);

            if (v1 < 0.65) {
              // Purple Vein Core
              if (rnd < 0.45) setV(x, y, z, "minecraft:amethyst_block");
              else if (rnd < 0.75) setV(x, y, z, "minecraft:budding_amethyst");
              else setV(x, y, z, "minecraft:crying_obsidian");
            } else if (v1 < 1.35) {
              // Purple Vein Sheath
              if (rnd < 0.55) setV(x, y, z, "minecraft:crying_obsidian");
              else if (rnd < 0.8) setV(x, y, z, "minecraft:amethyst_block");
              else setV(x, y, z, "minecraft:gilded_blackstone");
            } else if (v2 < 0.55) {
              // Cyan Thermal Core
              if (rnd < 0.6) setV(x, y, z, "minecraft:sea_lantern");
              else setV(x, y, z, "minecraft:prismarine_bricks");
            } else if (v2 < 1.25) {
              // Cyan Sheath
              if (rnd < 0.5) setV(x, y, z, "minecraft:gilded_blackstone");
              else if (rnd < 0.8) setV(x, y, z, "minecraft:prismarine_bricks");
              else setV(x, y, z, "minecraft:polished_blackstone_bricks");
            } else if (v3 < 1.1) {
              // Meteoric Iron Seam
              if (rnd < 0.5) setV(x, y, z, "minecraft:raw_iron_block");
              else if (rnd < 0.8) setV(x, y, z, "minecraft:deepslate_iron_ore");
              else setV(x, y, z, "minecraft:gilded_blackstone");
            } else {
              // Meteoric Iron Crust & Outer Shell
              if (distAxis > maxR - 1.25 || cut1 > 3.8 || cut2 > 3.8) {
                if (rnd < 0.3) setV(x, y, z, "minecraft:obsidian");
                else if (rnd < 0.55) setV(x, y, z, "minecraft:crying_obsidian");
                else if (rnd < 0.75) setV(x, y, z, "minecraft:gilded_blackstone");
                else if (rnd < 0.9) setV(x, y, z, "minecraft:polished_blackstone");
                else setV(x, y, z, "minecraft:cracked_deepslate_tiles");
              } else {
                // Dense inner core
                if (rnd < 0.45) setV(x, y, z, "minecraft:blackstone");
                else if (rnd < 0.75) setV(x, y, z, "minecraft:deepslate_iron_ore");
                else setV(x, y, z, "minecraft:obsidian");
              }
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 4. SATELLITE CRYSTAL SHARDS & IMPACT EJECTA SPINES
  // -------------------------------------------------------------
  const shards = [
    // North-West Star-Shard
    { rx: 7.2, rz: 7.8, tx: 5.0, tz: 5.5, h: 7, baseR: 1.7, core: "minecraft:amethyst_block", crust: "minecraft:crying_obsidian" },
    // South-East Radiant Spine
    { rx: 18.5, rz: 18.2, tx: 21.0, tz: 20.2, h: 8, baseR: 1.8, core: "minecraft:sea_lantern", crust: "minecraft:gilded_blackstone" },
    // South-West Crystal Spur
    { rx: 7.8, rz: 18.0, tx: 6.2, tz: 20.0, h: 6, baseR: 1.6, core: "minecraft:crying_obsidian", crust: "minecraft:obsidian" },
    // North-East Ore Monolith
    { rx: 18.2, rz: 7.5, tx: 20.2, tz: 5.8, h: 7, baseR: 1.7, core: "minecraft:raw_iron_block", crust: "minecraft:deepslate_iron_ore" },
  ];

  for (const s of shards) {
    for (let y = sy - 1; y <= sy + s.h; y++) {
      const prog = (y - sy) / s.h;
      if (prog <= 1.0) {
        const curX = s.rx + (s.tx - s.rx) * Math.max(0, prog);
        const curZ = s.rz + (s.tz - s.rz) * Math.max(0, prog);
        const curR = s.baseR * (1.0 - prog * 0.75);

        for (let dx = -Math.ceil(curR); dx <= Math.ceil(curR); dx++) {
          for (let dz = -Math.ceil(curR); dz <= Math.ceil(curR); dz++) {
            const x = Math.round(curX + dx);
            const z = Math.round(curZ + dz);
            const d = Math.hypot(x - curX, z - curZ);
            if (d <= curR) {
              const rnd = coordHash(x, y, z);
              if (d <= curR * 0.5) {
                setV(x, y, z, s.core);
              } else {
                setV(x, y, z, rnd < 0.6 ? s.crust : "minecraft:polished_blackstone");
              }
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 5. SMITHS' FORGES & EXTRACTION HEARTHS RINGED AROUND THE RIM
  // -------------------------------------------------------------
  // North Smelting Station (x: 12..14, z: 2..4)
  const nFloorY = floorHeights.get("13,3") || sy + 2;
  setV(13, nFloorY, 3, "minecraft:magma_block");
  setV(12, nFloorY, 3, makeStairs(themeStair, "east"));
  setV(14, nFloorY, 3, makeStairs(themeStair, "west"));
  setV(13, nFloorY, 2, makeStairs(themeStair, "south"));
  setV(12, nFloorY + 1, 2, stoneWall);
  setV(12, nFloorY + 2, 2, stoneWall);
  setV(12, nFloorY + 3, 2, "minecraft:soul_lantern[hanging=false]");
  setV(14, nFloorY + 1, 2, stoneWall);
  setV(14, nFloorY + 2, 2, stoneWall);
  setV(14, nFloorY + 3, 2, "minecraft:soul_lantern[hanging=false]");
  // Anvil block for star-metal forging
  setV(13, nFloorY, 4, "minecraft:raw_iron_block");
  setV(13, nFloorY + 1, 4, makeSlab(themeSlab, "bottom"));

  // South Smelting Station (x: 12..14, z: 22..24)
  const sFloorY = floorHeights.get("13,23") || sy + 2;
  setV(13, sFloorY, 23, "minecraft:crying_obsidian");
  setV(12, sFloorY, 23, makeStairs(themeStair, "east"));
  setV(14, sFloorY, 23, makeStairs(themeStair, "west"));
  setV(13, sFloorY, 24, makeStairs(themeStair, "north"));
  setV(12, sFloorY + 1, 24, stoneWall);
  setV(12, sFloorY + 2, 24, stoneWall);
  setV(12, sFloorY + 3, 24, "minecraft:soul_lantern[hanging=false]");
  setV(14, sFloorY + 1, 24, stoneWall);
  setV(14, sFloorY + 2, 24, stoneWall);
  setV(14, sFloorY + 3, 24, "minecraft:soul_lantern[hanging=false]");
  setV(13, sFloorY, 22, "minecraft:deepslate_iron_ore");
  setV(13, sFloorY + 1, 22, makeSlab(themeSlab, "bottom"));

  // East Smelting Station (x: 22..24, z: 12..14)
  const eFloorY = floorHeights.get("23,13") || sy + 2;
  setV(23, eFloorY, 13, "minecraft:sea_lantern");
  setV(23, eFloorY, 12, makeStairs(themeStair, "south"));
  setV(23, eFloorY, 14, makeStairs(themeStair, "north"));
  setV(24, eFloorY, 13, makeStairs(themeStair, "west"));
  setV(24, eFloorY + 1, 12, stoneWall);
  setV(24, eFloorY + 2, 12, stoneWall);
  setV(24, eFloorY + 3, 12, "minecraft:lantern[hanging=false]");
  setV(24, eFloorY + 1, 14, stoneWall);
  setV(24, eFloorY + 2, 14, stoneWall);
  setV(24, eFloorY + 3, 14, "minecraft:lantern[hanging=false]");
  setV(22, eFloorY, 13, "minecraft:gilded_blackstone");
  setV(22, eFloorY + 1, 13, makeSlab(themeSlab, "bottom"));

  // West Smelting Station (x: 2..4, z: 12..14)
  const wFloorY = floorHeights.get("3,13") || sy + 2;
  setV(3, wFloorY, 13, "minecraft:amethyst_block");
  setV(3, wFloorY, 12, makeStairs(themeStair, "south"));
  setV(3, wFloorY, 14, makeStairs(themeStair, "north"));
  setV(2, wFloorY, 13, makeStairs(themeStair, "east"));
  setV(2, wFloorY + 1, 12, stoneWall);
  setV(2, wFloorY + 2, 12, stoneWall);
  setV(2, wFloorY + 3, 12, "minecraft:soul_lantern[hanging=false]");
  setV(2, wFloorY + 1, 14, stoneWall);
  setV(2, wFloorY + 2, 14, stoneWall);
  setV(2, wFloorY + 3, 14, "minecraft:soul_lantern[hanging=false]");
  setV(4, wFloorY, 13, "minecraft:cracked_deepslate_tiles");
  setV(4, wFloorY + 1, 13, makeSlab(themeSlab, "bottom"));

  // -------------------------------------------------------------
  // 6. PROTRUDING AMETHYST CLUSTERS ON EXPOSED VEINS
  // -------------------------------------------------------------
  const clusterDirs = [
    { dx: 0, dy: 1, dz: 0, state: "minecraft:amethyst_cluster[facing=up]" },
    { dx: 0, dy: -1, dz: 0, state: "minecraft:amethyst_cluster[facing=down]" },
    { dx: 0, dy: 0, dz: -1, state: "minecraft:amethyst_cluster[facing=north]" },
    { dx: 0, dy: 0, dz: 1, state: "minecraft:amethyst_cluster[facing=south]" },
    { dx: -1, dy: 0, dz: 0, state: "minecraft:amethyst_cluster[facing=west]" },
    { dx: 1, dy: 0, dz: 0, state: "minecraft:amethyst_cluster[facing=east]" },
  ];

  for (let x = 7; x <= 20; x++) {
    for (let y = sy; y <= sy + 16; y++) {
      for (let z = 7; z <= 20; z++) {
        const block = getV(x, y, z);
        if (block === "minecraft:amethyst_block" || block === "minecraft:budding_amethyst") {
          for (const c of clusterDirs) {
            const nx = x + c.dx;
            const ny = y + c.dy;
            const nz = z + c.dz;
            if (getV(nx, ny, nz) === null) {
              const rnd = coordHash(nx, ny, nz);
              if (rnd < 0.35) {
                setV(nx, ny, nz, c.state);
              }
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 7. EMIT GRID DETERMINISTICALLY
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = getV(x, y, z);
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Star-Metal Meteorite",
    seatY: sy,
    anchors: {
      front: [cx, sy + 1, 0],
      approach_north: [cx, sy + 1, 0],
      approach_south: [cx, sy + 1, 26],
      north_forge: [13, nFloorY, 3],
      south_forge: [13, sFloorY, 23],
      east_forge: [23, eFloorY, 13],
      west_forge: [3, wFloorY, 13],
      meteorite_apex: [16, sy + 16, 15],
    },
  };
}

