export const envelope = [11, 14, 11];

export default function build(api) {
  const W = 11;
  const H = 14;
  const D = 11;
  const seatY = 3;

  const grid = new Array(W * H * D);
  for (let i = 0; i < grid.length; i++) {
    grid[i] = "";
  }

  function getIdx(x, y, z) {
    return (x * H + y) * D + z;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[getIdx(x, y, z)] = block;
    }
  }

  function getBlock(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[getIdx(x, y, z)];
    }
    return "";
  }

  function deleteBlock(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[getIdx(x, y, z)] = "";
    }
  }

  const themeStonePrimary = (api.theme && api.theme.stone && api.theme.stone.primary) ? api.theme.stone.primary : "minecraft:cobblestone";
  const themeStoneAccent = (api.theme && api.theme.stone && api.theme.stone.accent) ? api.theme.stone.accent : "minecraft:deepslate";
  const themeGroundScree = (api.theme && api.theme.ground && api.theme.ground.scree) ? api.theme.ground.scree : "minecraft:tuff";

  const COPPER_FAMILY = [
    "minecraft:raw_copper_block",
    "minecraft:copper_block",
    "minecraft:cut_copper",
    "minecraft:exposed_copper",
    "minecraft:oxidized_copper"
  ];

  const AMETHYST_FAMILY = [
    "minecraft:amethyst_block",
    "minecraft:budding_amethyst",
    "minecraft:amethyst_block"
  ];

  const instanceStyle = api.instance.index % 8;

  const leanAngle = api.random() * Math.PI * 2;
  const leanDist = 0.8 + api.random() * 1.2;
  const spireHeight = seatY + 7 + Math.floor(api.random() * 3);
  const baseSpireRadius = 2.0 + api.random() * 0.4;
  const craterRadius = 4.4 + (api.random() - 0.5) * 0.4;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - 5;
      const dz = z - 5;
      const dist = Math.hypot(dx, dz);

      if (dist <= craterRadius) {
        const localGround = seatY + api.heightAt(x, z);
        const rimLift = Math.max(0, (1 - dist / craterRadius) * 2.6 + Math.sin(dx * 1.8 + dz * 1.5) * 0.4);
        const topY = Math.round(seatY + rimLift);
        const bottomY = Math.max(0, Math.min(seatY, localGround - 1));

        for (let y = bottomY; y <= topY; y++) {
          if (y < seatY) {
            const fRoll = api.random();
            if (fRoll < 0.4) {
              setBlock(x, y, z, themeStoneAccent);
            } else if (fRoll < 0.7) {
              setBlock(x, y, z, "minecraft:deepslate");
            } else {
              setBlock(x, y, z, "minecraft:tuff");
            }
          } else if (dist > craterRadius - 1.2) {
            const rRoll = api.random();
            if (rRoll < 0.35) {
              setBlock(x, y, z, themeStonePrimary);
            } else if (rRoll < 0.65) {
              setBlock(x, y, z, themeGroundScree);
            } else if (rRoll < 0.85) {
              setBlock(x, y, z, "minecraft:basalt[axis=y]");
            } else {
              setBlock(x, y, z, "minecraft:blackstone");
            }
          } else {
            const sRoll = api.random();
            if (sRoll < 0.35) {
              setBlock(x, y, z, "minecraft:gilded_blackstone");
            } else if (sRoll < 0.6) {
              setBlock(x, y, z, "minecraft:polished_blackstone");
            } else if (sRoll < 0.8) {
              setBlock(x, y, z, "minecraft:crying_obsidian");
            } else {
              setBlock(x, y, z, "minecraft:magma_block");
            }
          }
        }
      }
    }
  }

  function pickSpireBlock(y, distRatio, angle) {
    const r = api.random();

    if (instanceStyle === 0) {
      if (r < 0.55) return AMETHYST_FAMILY[Math.floor(api.random() * AMETHYST_FAMILY.length)];
      if (r < 0.75) return "minecraft:crying_obsidian";
      return "minecraft:gilded_blackstone";
    }
    if (instanceStyle === 1) {
      if (r < 0.38) return "minecraft:crying_obsidian";
      if (r < 0.70) return "minecraft:magma_block";
      if (r < 0.88) return "minecraft:gilded_blackstone";
      return "minecraft:smooth_basalt";
    }
    if (instanceStyle === 2) {
      if (r < 0.55) return COPPER_FAMILY[Math.floor(api.random() * COPPER_FAMILY.length)];
      if (r < 0.80) return "minecraft:lodestone";
      return "minecraft:gilded_blackstone";
    }
    if (instanceStyle === 3) {
      if (r < 0.45) return "minecraft:raw_iron_block";
      if (r < 0.75) return "minecraft:lodestone";
      if (r < 0.90) return "minecraft:amethyst_block";
      return "minecraft:crying_obsidian";
    }
    if (instanceStyle === 4) {
      if (r < 0.30) return "minecraft:gilded_blackstone";
      if (r < 0.55) return "minecraft:amethyst_block";
      if (r < 0.80) return "minecraft:magma_block";
      return "minecraft:crying_obsidian";
    }
    if (instanceStyle === 5) {
      const band = Math.floor(y + angle * 1.5) % 4;
      if (band === 0) return "minecraft:budding_amethyst";
      if (band === 1) return "minecraft:lodestone";
      if (band === 2) return "minecraft:crying_obsidian";
      return "minecraft:gilded_blackstone";
    }
    if (instanceStyle === 6) {
      if (angle < Math.PI) {
        return r < 0.65 ? "minecraft:amethyst_block" : "minecraft:crying_obsidian";
      }
      return r < 0.65 ? COPPER_FAMILY[Math.floor(api.random() * COPPER_FAMILY.length)] : "minecraft:gilded_blackstone";
    }
    if (r < 0.35) return "minecraft:lodestone";
    if (r < 0.65) return "minecraft:oxidized_copper";
    if (r < 0.85) return "minecraft:gilded_blackstone";
    return "minecraft:crying_obsidian";
  }

  for (let y = seatY; y <= spireHeight; y++) {
    const t = (y - seatY) / (spireHeight - seatY);
    const cx = 5 + Math.cos(leanAngle) * leanDist * t;
    const cz = 5 + Math.sin(leanAngle) * leanDist * t;
    const curRadius = baseSpireRadius * (1 - t * 0.72);

    const minX = Math.floor(cx - curRadius - 1);
    const maxX = Math.ceil(cx + curRadius + 1);
    const minZ = Math.floor(cz - curRadius - 1);
    const maxZ = Math.ceil(cz + curRadius + 1);

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const d = Math.hypot(x - cx, z - cz);
        if (d <= curRadius) {
          const angle = Math.atan2(z - cz, x - cx) + Math.PI;
          setBlock(x, y, z, pickSpireBlock(y, d / curRadius, angle));
        }
      }
    }
  }

  const shardCount = 2 + (instanceStyle % 2);
  for (let i = 0; i < shardCount; i++) {
    const shardAngle = leanAngle + (Math.PI * 2 * (i + 1)) / shardCount + (api.random() - 0.5) * 0.5;
    const shardHeight = seatY + 4 + Math.floor(api.random() * 4);
    const shardOffset = 1.8 + api.random() * 0.7;
    const shardBaseRadius = 1.0 + api.random() * 0.4;

    for (let y = seatY + 1; y <= shardHeight; y++) {
      const st = (y - seatY - 1) / (shardHeight - seatY);
      const sx = 5 + Math.cos(shardAngle) * (shardOffset * (0.4 + 0.7 * st));
      const sz = 5 + Math.sin(shardAngle) * (shardOffset * (0.4 + 0.7 * st));
      const sr = shardBaseRadius * (1 - st * 0.75);

      const minX = Math.floor(sx - sr - 1);
      const maxX = Math.ceil(sx + sr + 1);
      const minZ = Math.floor(sz - sr - 1);
      const maxZ = Math.ceil(sz + sr + 1);

      for (let x = minX; x <= maxX; x++) {
        for (let z = minZ; z <= maxZ; z++) {
          if (Math.hypot(x - sx, z - sz) <= sr) {
            setBlock(x, y, z, pickSpireBlock(y, 0.5, shardAngle));
          }
        }
      }
    }
  }

  const ventX = 5 + (instanceStyle % 2 === 0 ? 0 : 1);
  const ventZ = 5 + (instanceStyle % 3 === 0 ? 0 : -1);
  const ventY = seatY;

  setBlock(ventX - 1, ventY, ventZ, "minecraft:gilded_blackstone");
  setBlock(ventX + 1, ventY, ventZ, "minecraft:crying_obsidian");
  setBlock(ventX, ventY, ventZ - 1, "minecraft:magma_block");
  setBlock(ventX, ventY, ventZ + 1, "minecraft:lodestone");

  const isSoulSmoke = instanceStyle === 1 || instanceStyle === 4 || instanceStyle === 6;
  if (isSoulSmoke) {
    setBlock(ventX, ventY, ventZ, "minecraft:soul_campfire[lit=true,signal_fire=true]");
  } else {
    setBlock(ventX, ventY, ventZ, "minecraft:campfire[lit=true,signal_fire=true]");
  }

  setBlock(ventX, ventY + 1, ventZ, "minecraft:iron_bars");
  deleteBlock(ventX, ventY + 2, ventZ);
  deleteBlock(ventX, ventY + 3, ventZ);

  const directions = [
    { dx: 0, dy: 1, dz: 0, facing: "up" },
    { dx: 0, dy: -1, dz: 0, facing: "down" },
    { dx: 0, dy: 0, dz: -1, facing: "north" },
    { dx: 0, dy: 0, dz: 1, facing: "south" },
    { dx: -1, dy: 0, dz: 0, facing: "west" },
    { dx: 1, dy: 0, dz: 0, facing: "east" }
  ];

  for (let x = 0; x < W; x++) {
    for (let y = seatY; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = getBlock(x, y, z);
        if (block !== "") {
          for (let d = 0; d < 6; d++) {
            const dir = directions[d];
            const nx = x + dir.dx;
            const ny = y + dir.dy;
            const nz = z + dir.dz;

            if (nx >= 0 && nx < W && ny >= seatY && ny < H && nz >= 0 && nz < D) {
              if (getBlock(nx, ny, nz) === "") {
                const roll = api.random();
                if (block.indexOf("amethyst") !== -1 && roll < 0.28) {
                  if (roll < 0.12) {
                    setBlock(nx, ny, nz, "minecraft:amethyst_cluster[facing=" + dir.facing + "]");
                  } else if (roll < 0.20) {
                    setBlock(nx, ny, nz, "minecraft:large_amethyst_bud[facing=" + dir.facing + "]");
                  } else {
                    setBlock(nx, ny, nz, "minecraft:small_amethyst_bud[facing=" + dir.facing + "]");
                  }
                } else if (block.indexOf("blackstone") !== -1 && dir.dy === 0 && roll < 0.14) {
                  setBlock(nx, ny, nz, "minecraft:polished_blackstone_stairs[facing=" + dir.facing + ",half=bottom]");
                }
              }
            }
          }
        }
      }
    }
  }

  let solidCount = 0;
  for (let i = 0; i < grid.length; i++) {
    if (grid[i] !== "") solidCount++;
  }

  if (solidCount < 520) {
    for (let x = 1; x < W - 1; x++) {
      for (let z = 1; z < D - 1; z++) {
        if (Math.hypot(x - 5, z - 5) <= 4.2) {
          for (let y = 1; y <= 2; y++) {
            if (getBlock(x, y, z) === "") {
              setBlock(x, y, z, themeStoneAccent);
            }
          }
        }
      }
    }
  }

  const visited = new Uint8Array(W * H * D);
  const queueX = new Int32Array(W * H * D);
  const queueY = new Int32Array(W * H * D);
  const queueZ = new Int32Array(W * H * D);
  let qHead = 0;
  let qTail = 0;

  const rootIdx = getIdx(5, seatY, 5);
  if (grid[rootIdx] !== "") {
    visited[rootIdx] = 1;
    queueX[qTail] = 5;
    queueY[qTail] = seatY;
    queueZ[qTail] = 5;
    qTail++;
  }

  const dxs = [1, -1, 0, 0, 0, 0];
  const dys = [0, 0, 1, -1, 0, 0];
  const dzs = [0, 0, 0, 0, 1, -1];

  while (qHead < qTail) {
    const cx = queueX[qHead];
    const cy = queueY[qHead];
    const cz = queueZ[qHead];
    qHead++;

    for (let d = 0; d < 6; d++) {
      const nx = cx + dxs[d];
      const ny = cy + dys[d];
      const nz = cz + dzs[d];
      if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
        const nIdx = getIdx(nx, ny, nz);
        if (grid[nIdx] !== "" && visited[nIdx] === 0) {
          visited[nIdx] = 1;
          queueX[qTail] = nx;
          queueY[qTail] = ny;
          queueZ[qTail] = nz;
          qTail++;
        }
      }
    }
  }

  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const i = getIdx(x, y, z);
        if (grid[i] !== "" && visited[i] === 0) {
          grid[i] = "";
        }
      }
    }
  }

  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = getBlock(x, y, z);
        if (blk !== "") {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  return {
    name: "starmetal_cluster",
    seatY: seatY,
    anchors: {
      center: [5, seatY, 5]
    }
  };
}
